FROM "ArtifactRatings" ar 
LIMIT 5;

SELECT PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY "HIST_sign") as hist_90th,
       PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY (rating_profile->>'cultural_score')::int) as cultural_90th
FROM "ArtifactRatings";

